{"path": "src/debounce.js", "content": "// debounce(fn, ms): returns a function that delays calling fn until ms have passed without
// another call; fn gets the arguments of the last call. The returned function has .cancel()
// (drop the pending call) and .flush() (run the pending call now, if any).
export function debounce(fn, ms) {
  let timer;
  let pending = null; // { ctx, args } of the last call, or null when nothing is pending

  const run = () => {
    const { ctx, args } = pending;
    pending = null;
    timer = undefined;
    return fn.apply(ctx, args);
  };

  function debounced(...args) {
    clearTimeout(timer);
    pending = { ctx: this, args };
    timer = setTimeout(run, ms);
  }

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = undefined;
    pending = null;
  };

  debounced.flush = () => {
    if (!pending) return undefined;
    clearTimeout(timer);
    return run();
  };

  return debounced;
}
"}

{"path": "test/debounce.test.js", "content": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import { debounce } from '../src/debounce.js';

test('exists', () => assert.equal(typeof debounce(() => {}, 10), 'function'));

test('calls once with the last arguments after the delay', (t) => {
  t.mock.timers.enable({ apis: ['setTimeout'] });
  const calls = [];
  const d = debounce((...a) => calls.push(a), 100);
  d(1);
  t.mock.timers.tick(50);
  d(2, 3);
  t.mock.timers.tick(99);
  assert.deepEqual(calls, []);
  t.mock.timers.tick(1);
  assert.deepEqual(calls, [[2, 3]]);
  t.mock.timers.tick(500);
  assert.equal(calls.length, 1);
});

test('cancel drops the pending call', (t) => {
  t.mock.timers.enable({ apis: ['setTimeout'] });
  let n = 0;
  const d = debounce(() => n++, 100);
  d();
  d.cancel();
  t.mock.timers.tick(200);
  assert.equal(n, 0);
  d.flush();
  assert.equal(n, 0);
});

test('flush runs the pending call now, only once', (t) => {
  t.mock.timers.enable({ apis: ['setTimeout'] });
  const calls = [];
  const d = debounce((x) => calls.push(x), 100);
  d.flush();
  assert.deepEqual(calls, []);
  d('a');
  d('b');
  d.flush();
  assert.deepEqual(calls, ['b']);
  t.mock.timers.tick(200);
  d.flush();
  assert.deepEqual(calls, ['b']);
});
"}

{"summary": "`debounce` in `src/debounce.js` now does what its comment says: calls within the delay are collapsed into one call to `fn`, using the arguments of the last call. `.cancel()` drops the pending call, and `.flush()` runs it right away. If nothing is pending, `.flush()` does nothing.

It saves the last call's arguments and `this`. Running the call, either from the timer or from `.flush()`, clears that saved state, so each pending call runs at most once.

I added three tests to `test/debounce.test.js`. They use Node's fake timers to cover the delay, last-arguments-win, `cancel` and `flush` behaviour. `npm test` passes all 4 tests.", "outputs": ["src/debounce.js"]}
